import{_ as r,o as e,c as a,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"外觀","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/appearance.md","filePath":"zh-HK/user-guide/settings/appearance.md","lastUpdated":1785993908000}'),o={name:"zh-HK/user-guide/settings/appearance.md"};function n(i,t,l,g,p,d){return e(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="外觀" tabindex="-1">外觀 <a class="header-anchor" href="#外觀" aria-label="Permalink to &quot;外觀&quot;">​</a></h1><p>固定在側邊欄底部、<a href="./about.html">關於</a> 的上方。分兩組:<strong>主題模式</strong>和主題選擇器本身。</p><h2 id="主題模式" tabindex="-1">主題模式 <a class="header-anchor" href="#主題模式" aria-label="Permalink to &quot;主題模式&quot;">​</a></h2><p>三張卡片，點擊即可切換:</p><ul><li><strong>淺色</strong> —— 固定使用單一主題，下方網格只篩選淺色風格的主題。</li><li><strong>深色</strong> —— 同上，只篩選深色風格的主題。</li><li><strong>跟隨系統</strong>(淺深分屏預覽)—— Lertaro 會在你分別指定的兩個主題之間切換——一個用於 Windows 處於淺色模式時，一個用於深色模式時——而不是固定用一個主題，並且 Windows 自己的設定一變化就立刻生效(不需要重啓)。</li></ul><p>在<strong>淺色</strong>和<strong>深色</strong>之間切換時，會自動跳到該風格下你上一次選過的主題(跟&quot;跟隨系統&quot;用來記住淺/深兩側選擇的是同一份記憶)，所以來回切換不會丟失任一側已經選好的主題。</p><h2 id="介面主題" tabindex="-1">介面主題 <a class="header-anchor" href="#介面主題" aria-label="Permalink to &quot;介面主題&quot;">​</a></h2><p>選中上方的<strong>淺色</strong>或<strong>深色</strong>時，下面是一個只列出對應風格主題的卡片網格。選中<strong>跟隨系統</strong> 時，網格會拆成兩組:<strong>淺色主題</strong>和<strong>深色主題</strong>——兩者預設取符合對應風格、且恰好排在最前面的那個已安裝主題，具體有哪些主題完全取決於安裝了哪些主題插件。</p><p>每個主題都以卡片形式展示，而不只是一個名字:卡片裏是一個用該主題配色渲染的快速搜尋視窗縮略圖(搜尋框加幾行搜尋結果，其中一行顯示為選中態)，切換前就能看到主題的實際觀感。當前生效的主題卡片上會有一個勾選徽標。</p><p>內置與隨包主題插件:</p><ul><li><strong>CoreExtensions</strong>(內置)—— 淺色、深色、北歐藍、櫻花粉、賽博朋克。</li><li><strong>AnimeThemes</strong>(隨包提供，需已安裝並啓用)—— 新世紀、櫻花盛開、天氣之子。</li><li><strong>臻選主題 Curated Themes</strong>(隨包提供，需已安裝並啓用)—— 十組淺色/深色成對主題:冰川藍、陶土棕、森林綠、紫水晶、緋紅、石墨灰、靛藍夜、薄荷青、香檳金、琥珀金。</li></ul><p>其他主題插件也可以用同樣的方式往網格裏再加卡片。</p>',12)])])}const c=r(o,[["render",n]]);export{h as __pageData,c as default};
